// Icon lookup for `[icon: name]`.
// - Tech logos (`postgres`, `k8s`, `redis`, ...) draw a Simple Icons logo (CC0-1.0).
// - General names (`users`, `key`, `shield`, ...) draw a Lucide icon (ISC).
// - Cloud vendor names (`aws-ec2`, `gcp-cloud-sql`, `azure-key-vaults`, ...) map to a generic glyph by
//   service phrase or keyword, drawn with Lucide. No AWS / Google Cloud / Azure artwork is bundled.
// - Anything else gets our own neutral placeholder.
// Only the placeholder (`GLYPHS.placeholder`) is our own artwork; it is the fallback.
// Icon data is generated by scripts/build-icons.mjs into icon-data.ts.

import { LUCIDE_ICONS, SIMPLE_ICONS } from './icon-data.ts';

/** Generic glyph names. `Glyph` and the exact-name lookup both derive from this one list. */
const GLYPH_LIST = [
  'user',
  'users',
  'server',
  'database',
  'monitor',
  'phone',
  'cloud',
  'queue',
  'balancer',
  'function',
  'bucket',
  'bolt',
  'container',
  'lock',
  'globe',
  'flag',
  'mail',
  'file',
  'gear',
  'chart',
  'code',
  'bell',
  'search',
  'shield',
  'brain',
  'workflow',
  'router',
  'layers',
  'package',
  'archive',
  'clock',
  'placeholder',
] as const;

export type Glyph = (typeof GLYPH_LIST)[number];

/** Our own artwork: only the neutral placeholder is drawn. Every other glyph name is drawn with Lucide (see LUCIDE_FOR_GLYPH). */
export const GLYPHS = {
  placeholder: 'M4 4h16v16H4z M9 9h6v6H9z',
} as const satisfies Record<'placeholder', string>;

/** An icon name equal to one of the glyph names picks that glyph before keywords are tried. */
const GLYPH_NAMES: ReadonlySet<string> = new Set<string>(GLYPH_LIST);

/**
 * Service phrase → glyph, checked before the keywords: runs of whole words in the icon name
 * (`virtual-machines` in `azure-virtual-machines`). They name cloud services whose single words would
 * pick the wrong glyph (`machine-learning`, `step-functions`, `key-management-service`).
 */
const PHRASES: [Glyph, string[]][] = [
  ['brain', ['machine-learning', 'vertex-ai', 'cognitive-services']],
  ['workflow', ['step-functions', 'logic-apps', 'data-factory', 'cloud-build', 'cloud-deploy']],
  ['router', ['nat-gateway', 'nat-gateways', 'vpn-gateway', 'vpn-gateways', 'transit-gateway', 'direct-connect', 'private-link', 'cloud-nat', 'cloud-vpn']],
  ['layers', ['resource-groups', 'resource-group', 'management-groups', 'management-group', 'control-tower']],
  ['package', ['container-registry', 'container-registries', 'artifact-registry']],
  ['archive', ['site-recovery']],
  ['lock', ['key-management', 'certificate-manager', 'managed-identities', 'managed-identity', 'identity-platform']],
  ['users', ['active-directory', 'entra-id']],
  ['server', ['virtual-machine', 'virtual-machines', 'auto-scaling']],
  ['globe', ['route-53', 'virtual-network', 'virtual-networks']],
  ['balancer', ['front-door', 'front-doors', 'traffic-manager', 'global-accelerator']],
  ['queue', ['event-hubs', 'event-hub', 'event-grid', 'cloud-tasks']],
  ['chart', ['azure-monitor', 'log-analytics', 'application-insights']],
  ['mail', ['simple-email-service']],
  ['gear', ['systems-manager']],
  ['bucket', ['data-lake']],
  ['container', ['cloud-run']],
];

/** Keyword → glyph, checked in order against the `-`/`_`/space separated words of the icon name. */
const KEYWORDS: [Glyph, string[]][] = [
  ['shield', ['shield', 'waf', 'firewall', 'firewalls', 'guardduty', 'defender', 'sentinel', 'armor', 'bastion', 'bastions', 'policy']],
  ['router', ['vpn', 'nat', 'expressroute', 'interconnect', 'privatelink']],
  ['package', ['ecr', 'registry', 'registries']],
  ['workflow', ['workflow', 'workflows', 'glue', 'dataflow', 'composer', 'airflow', 'codepipeline', 'codebuild', 'devops']],
  ['layers', ['organizations', 'subscriptions', 'cloudformation', 'stack']],
  ['archive', ['backup', 'backups', 'snapshot', 'snapshots']],
  ['clock', ['scheduler', 'schedule']],
  ['users', ['users', 'team', 'teams', 'group', 'people', 'customers']],
  ['user', ['user', 'person', 'customer', 'admin', 'account', 'profile']],
  ['database', ['database', 'db', 'rds', 'sql', 'aurora', 'dynamodb', 'dynamo', 'postgres', 'postgresql', 'mysql', 'mongo', 'mongodb', 'spanner', 'bigtable', 'firestore', 'cosmos', 'table', 'redshift', 'bigquery', 'warehouse', 'synapse', 'datastore', 'athena']],
  ['bolt', ['cache', 'redis', 'elasticache', 'memcached', 'memorystore', 'cdn', 'cloudfront']],
  ['queue', ['queue', 'sqs', 'sns', 'kafka', 'pubsub', 'kinesis', 'rabbitmq', 'eventbridge', 'stream', 'bus', 'mq', 'msk', 'eventarc', 'signalr']],
  ['balancer', ['elb', 'alb', 'nlb', 'balancer', 'lb', 'load', 'gateway', 'router', 'ingress', 'proxy', 'nginx', 'gateways', 'balancers', 'balancing']],
  ['function', ['lambda', 'function', 'functions', 'serverless']],
  ['bucket', ['s3', 'bucket', 'storage', 'blob', 'gcs', 'efs', 'disk', 'volume', 'ebs', 'archive', 'glacier', 'filestore', 'datalake']],
  ['container', ['container', 'docker', 'kubernetes', 'k8s', 'eks', 'ecs', 'gke', 'aks', 'fargate', 'pod', 'package', 'box']],
  ['server', ['server', 'ec2', 'compute', 'vm', 'instance', 'host', 'engine', 'node', 'backend', 'service', 'app', 'vms', 'autoscaling', 'emr', 'dataproc']],
  ['lock', ['lock', 'auth', 'iam', 'security', 'secret', 'secrets', 'key', 'kms', 'cognito', 'vault', 'identity', 'certificate', 'certificates']],
  ['globe', ['globe', 'internet', 'web', 'dns', 'route53', 'domain', 'world', 'www', 'network', 'vpc', 'vnet', 'subnet']],
  ['monitor', ['monitor', 'browser', 'desktop', 'laptop', 'client', 'frontend', 'screen', 'ui', 'amplify']],
  ['phone', ['phone', 'mobile', 'ios', 'android', 'tablet']],
  ['mail', ['mail', 'email', 'ses', 'smtp', 'inbox', 'message']],
  ['file', ['file', 'document', 'doc', 'docs', 'page', 'pdf', 'log', 'logs', 'logging', 'cloudtrail']],
  ['gear', ['gear', 'settings', 'config', 'worker', 'job', 'jobs', 'cron', 'batch', 'pipeline', 'tool', 'tools']],
  ['chart', ['chart', 'analytics', 'metrics', 'dashboard', 'cloudwatch', 'grafana', 'prometheus', 'stats', 'monitoring', 'insights', 'quicksight', 'looker']],
  ['code', ['code', 'api', 'github', 'git', 'gitlab', 'terminal', 'script', 'sdk', 'appsync', 'apigee']],
  ['bell', ['bell', 'notification', 'notifications', 'alert', 'alerts', 'alarm']],
  ['search', ['search', 'elasticsearch', 'opensearch', 'find', 'query']],
  ['flag', ['flag', 'milestone', 'start', 'goal']],
  ['brain', ['ai', 'ml', 'sagemaker', 'bedrock', 'openai', 'vertex', 'llm']],
  // Last: a vendor prefix alone says nothing about the service, so every keyword above wins over it.
  ['cloud', ['cloud', 'aws', 'gcp', 'azure']],
];

/** Pick a glyph for an icon name. Exact glyph names win, then keywords, then the placeholder. */
export function glyphFor(name: string): Glyph {
  const n = name.trim().toLowerCase();
  if (GLYPH_NAMES.has(n)) return n as Glyph;
  const words = n.split(/[-_\s.]+/).filter(Boolean);
  const dashed = `-${words.join('-')}-`;
  for (const [glyph, keys] of PHRASES) {
    if (keys.some((k) => dashed.includes(`-${k}-`))) return glyph;
  }
  for (const [glyph, keys] of KEYWORDS) {
    if (words.some((w) => keys.includes(w))) return glyph;
  }
  return 'placeholder';
}

/** Lucide artwork for each generic glyph. `placeholder` stays our own. */
const LUCIDE_FOR_GLYPH: Record<Exclude<Glyph, 'placeholder'>, string> = {
  user: 'user',
  users: 'users',
  server: 'server',
  database: 'database',
  monitor: 'monitor',
  phone: 'smartphone',
  cloud: 'cloud',
  queue: 'columns-3',
  balancer: 'network',
  function: 'square-function',
  bucket: 'hard-drive',
  bolt: 'zap',
  container: 'box',
  lock: 'lock',
  globe: 'globe',
  flag: 'flag',
  mail: 'mail',
  file: 'file-text',
  gear: 'settings',
  chart: 'chart-column',
  code: 'code',
  bell: 'bell',
  search: 'search',
  shield: 'shield',
  brain: 'brain',
  workflow: 'workflow',
  router: 'router',
  layers: 'layers',
  package: 'package',
  archive: 'archive',
  clock: 'clock',
};

/** Other spellings of bundled Lucide names (`-` separated). */
const LUCIDE_ALIASES: ReadonlyMap<string, string> = new Map([
  ['home', 'house'],
  ['warning', 'triangle-exclamation-point'],
  ['filter', 'funnel'],
  ['calendar-days', 'calendar'],
  ['chat', 'message-square'],
  ['payment', 'credit-card'],
  ['cart', 'shopping-cart'],
  ['idea', 'lightbulb'],
]);

/**
 * Tech logo names, compared with separators removed (`node-js` = `nodejs`). Keys are what people
 * write in Eraser-style code; values are bundled Simple Icons slugs. `vault` and `node` are left
 * out on purpose: they usually mean a generic vault or server, not the product.
 */
const BRANDS: ReadonlyMap<string, string> = new Map([
  ...[...SIMPLE_ICONS.keys()].filter((k) => k !== 'vault').map((k): [string, string] => [k, k]),
  ['postgres', 'postgresql'],
  ['pg', 'postgresql'],
  ['mongo', 'mongodb'],
  ['k8s', 'kubernetes'],
  ['nodejs', 'nodedotjs'],
  ['golang', 'go'],
  ['reactjs', 'react'],
  ['nextjs', 'nextdotjs'],
  ['rails', 'rubyonrails'],
  ['springboot', 'spring'],
  ['envoy', 'envoyproxy'],
  ['hashicorpvault', 'vault'],
  ['azuredatabricks', 'databricks'],
]);

export type IconSet = 'simple-icons' | 'lucide' | 'own';

export interface ResolvedIcon {
  set: IconSet;
  /** Key inside the set (Lucide name, Simple Icons slug or own glyph). */
  key: string;
  /** Path data on a 24x24 grid. */
  d: string;
  /** true: paint with fill (logos). false: paint with stroke (outline icons). */
  fill: boolean;
  /** Brand colour for logos. */
  hex?: string;
}

/** Resolve an icon name: tech logo, then exact Lucide name, then glyph keyword, then placeholder. */
export function iconFor(name: string): ResolvedIcon {
  const n = name.trim().toLowerCase();
  const brand = BRANDS.get(n.replace(/[-_\s.]+/g, ''));
  const logo = brand === undefined ? undefined : SIMPLE_ICONS.get(brand);
  if (brand !== undefined && logo) return { set: 'simple-icons', key: brand, d: logo.d, fill: true, hex: logo.hex };
  const dashed = n.split(/[_\s]+/).filter(Boolean).join('-');
  const lucideKey = LUCIDE_ALIASES.get(dashed) ?? dashed;
  const outline = LUCIDE_ICONS.get(lucideKey);
  if (outline !== undefined) return { set: 'lucide', key: lucideKey, d: outline, fill: false };
  const glyph = glyphFor(n);
  if (glyph !== 'placeholder') {
    const key = LUCIDE_FOR_GLYPH[glyph];
    const d = LUCIDE_ICONS.get(key);
    if (d !== undefined) return { set: 'lucide', key, d, fill: false };
  }
  return { set: 'own', key: 'placeholder', d: GLYPHS.placeholder, fill: false };
}
